package net.hivel.islandsrpg.drop;
import net.hivel.islandsrpg.IslandsRPGPlugin; import net.hivel.islandsrpg.data.PlayerData; import net.hivel.islandsrpg.util.*; import org.bukkit.*; import org.bukkit.configuration.ConfigurationSection; import org.bukkit.entity.Player; import org.bukkit.inventory.ItemStack; import java.util.*; import java.util.concurrent.ThreadLocalRandom;
public class DropService { private final IslandsRPGPlugin plugin; public DropService(IslandsRPGPlugin p){plugin=p;} public DropDefinition parse(String id, ConfigurationSection s){try{DropType t=DropType.valueOf(s.getString("type","ITEM")); Material m=s.contains("material")?Material.matchMaterial(s.getString("material")):null; return new DropDefinition(id,t,m,s.getString("display-name"),s.getDouble("chance",100),s.getInt("min",1),s.getInt("max",1),s.getString("weapon-id"),s.getString("magic-item-id"),s.getStringList("commands"));}catch(Exception e){plugin.getLogger().warning("Invalid drop "+id); return null;}} public void roll(Player p, Collection<DropDefinition> drops, Location loc){PlayerData d=plugin.data().get(p); double luck=plugin.stats().luckDropBonus(d); for(DropDefinition drop:drops){double chance=drop.chance()*(1+luck); if(ThreadLocalRandom.current().nextDouble(100)>chance)continue; int amount=NumberUtil.rand(drop.min(),drop.max()); switch(drop.type()){case MONEY -> plugin.currency().addMoney(p,amount); case FRAGMENTS -> plugin.currency().addFragments(p,amount); case ITEM -> { if(drop.material()==null){plugin.getLogger().warning("Invalid material in drop "+drop.id()); break;} ItemStack item=new ItemBuilder(drop.material()).name(drop.displayName()==null?"":drop.displayName()).build(); item.setAmount(amount); loc.getWorld().dropItemNaturally(loc,item);} case WEAPON -> {ItemStack item=plugin.weapons().item(drop.weaponId()); if(item!=null) loc.getWorld().dropItemNaturally(loc,item); else plugin.getLogger().warning("Invalid weapon drop "+drop.weaponId());} case MAGIC_ITEM -> {ItemStack item=plugin.magic().item(drop.magicItemId()); if(item!=null) loc.getWorld().dropItemNaturally(loc,item); else plugin.getLogger().warning("Invalid magic drop "+drop.magicItemId());} case COMMAND -> drop.commands().forEach(cmd->Bukkit.dispatchCommand(Bukkit.getConsoleSender(),cmd.replace("%player%",p.getName()))); } } } }
